// Same as prompts.py run: the prompt, its hard limits, the offer and the rules.
const PROMPTS = [{"id": "first-line", "name": "First line from one fact", "channel": "email", "max_words": "25", "max_questions": "0", "text": "Write the opening line of a cold email to this person. Build it on ONE fact from their data (their role, months in the job, company growth, company description or headline). Say why that fact made you write. Do not pitch the product in this line. Do not flatter."}, {"id": "short-email", "name": "Short problem-first email", "channel": "email", "max_words": "90", "max_questions": "1", "text": "Write a cold email body (no subject, no signature) to this person. Structure: one line on a fact from their data, one or two lines on the problem the offer solves for someone in their role, one line of proof from the offer, then one question as the call to action. Plain words, no buzzwords."}, {"id": "subject-lines", "name": "Three subject lines", "channel": "email", "max_words": "18", "max_questions": "3", "min_facts": "0", "text": "Write three subject lines for a cold email to this person, one per line, each under six words, in lowercase like a note from a colleague. At least one refers to their company or role. No clickbait, no emoji, no \"re:\" or \"fwd:\"."}, {"id": "follow-up", "name": "Follow-up with a new angle", "channel": "email", "max_words": "60", "max_questions": "1", "text": "Write the second email of a sequence to this person, sent four days after a first email with no reply. Bring ONE new angle (a different problem, a different proof, or a different fact from their data). Never say you are following up or bumping the thread. End with one easy question."}, {"id": "breakup", "name": "Last email that gives an easy out", "channel": "email", "max_words": "45", "max_questions": "1", "text": "Write the last email of a sequence to this person, after two emails with no reply. Be short and polite, give them an easy way to say no or to point you to someone else, and do not guilt them. Mention their company once."}, {"id": "linkedin-note", "name": "LinkedIn connection note", "channel": "linkedin", "max_words": "50", "max_chars": "280", "max_questions": "1", "text": "Write a LinkedIn connection request note to this person, under 280 characters. Build it on one fact from their data and say why you want to connect. No pitch, no link, no meeting request."}, {"id": "objection-reply", "name": "Reply to \"we already have a provider\"", "channel": "email", "max_words": "70", "max_questions": "1", "text": "This person replied to your cold email: \"Thanks, but we already have a data provider.\" Write your reply. Agree first, then offer one specific reason to compare (from the offer, not invented), and ask one low-effort question. Never argue, never criticise their provider."}, {"id": "referral-ask", "name": "Ask for the right person", "channel": "email", "max_words": "50", "max_questions": "1", "text": "Write a short email asking this person who on their team owns outbound list building, in case it is not them. Use one fact from their data to show you looked. One question only."}], OFFER = {"sender": "Roy, Evaboot", "product": "Evaboot exports LinkedIn Sales Navigator searches and lists to a clean spreadsheet with verified emails.", "for_who": "sales leaders who build outbound lists from Sales Navigator", "problem": "copying leads by hand from Sales Navigator, bounced emails and messy job titles", "proof": "more than 200,000 users (evaboot.com)", "call_to_action": "a 15-minute call, or a trial account"}, RULES = "Use ONLY the facts in the lead JSON and the offer. Never invent a number, a news item, a customer, a tool they use or anything you cannot see in the data. Never guess anyone's gender: use the first name, \"you\" or the role. Write in plain English, no emoji.\n\nReturn ONLY a JSON object: {\"text\": \"<the message>\", \"facts_used\": [\"<the value of each fact from the lead JSON you used, copied exactly, without its key>\"]}", FIELDS = [["First name", "first_name"], ["Job title", "title"], ["Company", "company"], ["Industry", "industry"], ["Company size", "company_size"], ["Months in role", "months_in_role"], ["Company growth in 1 year (%)", "company_growth_1y_pct"], ["Headline", "headline"], ["Company description", "company_description"]];
const f = $('One lead, one prompt').first().json;
const p = PROMPTS.find(x => x.name === f['Prompt']);
const lead = {};
for (const [label, key] of FIELDS) if (String(f[label] ?? '').trim()) lead[key] = String(f[label]).trim();
const limits = `Hard limits: at most ${p.max_words} words` + (p.max_chars ? ` and ${p.max_chars} characters` : '') + `, at most ${p.max_questions} question mark(s). Count before you answer.`;
return [{ json: { prompt: p, lead, system: `${p.text}\n\n${limits}\n\nThe offer:\n${JSON.stringify(OFFER, null, 1)}\n\n${RULES}`, user: JSON.stringify(lead) } }];

// Same as prompts.py check.
const BANNED = ["hope this email finds you", "hope you're well", "just following up", "following up on", "bumping this", "circle back", "touch base", "quick question", "game-changer", "game changer", "revolutionize", "revolutionise", "synergy", "leverage", "cutting-edge", "best-in-class", "i wanted to reach out", "free", "guarantee", "100%", "act now", "limited time"];
const { prompt: p, lead } = $('Build the prompt').first().json;
const out = $json.output || {};
const text = String(out.text || ''), used = out.facts_used || [];
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9%]+/g, ' ').trim();
const data = norm(Object.values(lead).join(' ')), offer = norm("Roy, Evaboot Evaboot exports LinkedIn Sales Navigator searches and lists to a clean spreadsheet with verified emails. sales leaders who build outbound lists from Sales Navigator copying leads by hand from Sales Navigator, bounced emails and messy job titles more than 200,000 users (evaboot.com) a 15-minute call, or a trial account");
const problems = [];
const words = text.split(/\s+/).filter(Boolean).length;
if (words > +p.max_words) problems.push(`${words} words, max ${p.max_words}`);
if (p.max_chars && text.length > +p.max_chars) problems.push(`${text.length} characters, max ${p.max_chars}`);
const q = (text.match(/\?/g) || []).length;
if (q > +p.max_questions) problems.push(`${q} questions, max ${p.max_questions}`);
for (const b of BANNED) if (new RegExp('(?<![a-z])' + b.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![a-z])').test(text.toLowerCase())) problems.push('banned phrase: ' + b);
if (/\b(he|she|him|her|his|hers)\b/i.test(text)) problems.push('guesses a gender');
if (used.length < +(p.min_facts ?? 1)) problems.push("uses no fact from the lead's data");
for (let fact of used) { fact = String(fact).replace(/^\W*[a-z_0-9]+\W*:\s*/, '').replace(/^"|"$/g, '');
  if (norm(fact) && !data.includes(norm(fact)) && !offer.includes(norm(fact))) problems.push('claims a fact that is not in the data: ' + fact.slice(0, 60)); }
for (const num of text.match(/\d[\d,.]*%?/g) || []) { const n = norm(num).replace(/ /g, '').replace(/%$/, '');
  if (n && !data.replace(/ /g, '').includes(n) && !offer.replace(/ /g, '').includes(n)) problems.push('number not in the data or the offer: ' + num); }
return [{ json: { prompt: p.name, text, facts_used: used.join(' | '), check: problems.length ? 'FAIL: ' + problems.join('; ') : 'OK' } }];
